abstract class THTheme {
  THTheme._();
  static ThemeData get light => _build(Brightness.light, THColors.light);
  static ThemeData get dark => _build(Brightness.dark, THColors.dark);

  static ThemeData _build(Brightness b, THColors c) {
    final scheme = ColorScheme(
      brightness: b,
      primary: c.brand,
      onPrimary: c.onBrand,
      secondary: c.accent,
      onSecondary: c.onAccent,
      error: c.danger,
      onError: Colors.white,
      surface: c.surface,
      onSurface: c.text,
      outline: c.line,
    );
    return ThemeData(
      useMaterial3: true,
      brightness: b,
      colorScheme: scheme,
      scaffoldBackgroundColor: c.paper,
      fontFamily: THFonts.body,
      dividerColor: c.line,
      extensions: <ThemeExtension<dynamic>>[c],
    );
  }
}
